inputs.customFunctionJavascriptFunction:
const axios = require('axios');

const userId = $flow.sessionId?.split('|')[0];
if (!userId) { return 'No userId available.'; }

// A learner can be in several courses, and a learning record is about one of
// them: concepts mastered in one course say nothing about another. Filtering
// on the learner alone returns whichever record Weaviate finds first, and
// limit: 1 makes that silent — this agent would read another course's record
// as its own.
const courseId = '{{COURSE_ID}}';

const weaviateUrl    = 'http://smartrag-weaviate:8080/v1/graphql';
const weaviateApiKey = $vars?.WEAVIATE_API_KEY || '';

try {
  const response = await axios.post(
    weaviateUrl,
    { query: `{ Get { UserMemory(
        where: { operator: And operands: [
          { path: ["user_id"]   operator: Equal valueText: ${JSON.stringify(String(userId))} }
          { path: ["course_id"] operator: Equal valueText: ${JSON.stringify(String(courseId))} }
        ] }
        limit: 1
      ) { concepts_mastered concepts_struggling open_questions learning_patterns summary chapter } } }` },
    { headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + weaviateApiKey } }
  );
  const mem = response.data?.data?.Get?.UserMemory?.[0];
  if (!mem) { return 'No prior learning record found.'; }

  return [
    'Learning record:',
    '- Mastered concepts: ' + ((mem.concepts_mastered || []).join(', ') || 'none'),
    '- Struggling with: '   + ((mem.concepts_struggling || []).join(', ') || 'none'),
    '- Open questions: '    + ((mem.open_questions || []).join(', ') || 'none'),
    '- Learning patterns: ' + (mem.learning_patterns || 'unknown'),
    '- Last studied: '      + (mem.chapter || 'unknown')
  ].join('\n');

} catch (error) {
  return 'ERROR: ' + error.message;
}

