inputs.customFunctionJavascriptFunction:
const axios = require('axios');

const userId      = $flow.sessionId?.split('|')[0];
const userMessage = $flow.input;
if (!userId || !userMessage) { return 'No userId or message available.'; }

// The learner's own history, but only from this course. Without the course
// this search reaches across every course the learner is in and quotes those
// conversations back to them as "relevant prior conversations" — in this
// course's agent, in this course's prompt.
const courseId = '{{COURSE_ID}}';

const embeddingBaseUrl = $vars?.EMBEDDING_BASE_URL || 'https://api.openai.com/v1';
const embeddingModel   = $vars?.EMBEDDING_MODEL    || 'text-embedding-3-small';
const embeddingApiKey  = $vars?.EMBEDDING_API_KEY  || '';
const weaviateUrl      = 'http://smartrag-weaviate:8080/v1/graphql';
const weaviateApiKey   = $vars?.WEAVIATE_API_KEY   || '';

try {
  // 1. Generate embedding via OpenAI-compatible API
  const embedResponse = await axios.post(
    embeddingBaseUrl + '/embeddings',
    { model: embeddingModel, input: userMessage },
    { headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + embeddingApiKey
    }}
  );
  const vector = embedResponse.data?.data?.[0]?.embedding;
  if (!vector) { return 'Could not generate embedding for history search.'; }

  // 2. nearVector search — across this course's agents, this learner only
  const hitsResponse = await axios.post(
    weaviateUrl,
    { query: `{ Get { ChatHistory(
        nearVector: { vector: ${JSON.stringify(vector)}, certainty: 0.4 }
        where: { operator: And, operands: [
          { path: ["user_id"],   operator: Equal, valueText: ${JSON.stringify(String(userId))} },
          { path: ["course_id"], operator: Equal, valueText: ${JSON.stringify(String(courseId))} },
          { path: ["role"],      operator: Equal, valueText: "user" }
        ]}
        limit: 5
      ) { text session_id message_index } } }` },
    { headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + weaviateApiKey } }
  );

  // 3. Filter out current session
  const hits = (hitsResponse.data?.data?.Get?.ChatHistory || [])
    .filter(h => h.session_id !== $flow.sessionId);

  if (hits.length === 0) { return 'No relevant prior conversations found.'; }

  return 'Relevant prior conversations:\n' + hits
    .map(h => `- "${h.text.substring(0, 150)}..."`)
    .join('\n');

} catch (error) {
  return 'ERROR: ' + error.message;
}

