inputs.customFunctionJavascriptFunction:
const axios = require('axios');

const topic = $flow.state.current_topic;
// Substituted at import, like the collection name. Without it the
// query matched a concept of the same name in any course, so one
// course's prerequisites reached another course's learners.
const courseId = '{{COURSE_ID}}';
if (!topic || topic === 'general') { return 'No specific topic — no prerequisites to load.'; }

const neo4jUrl      = 'http://smartrag-neo4j:7474/db/neo4j/tx/commit';
const neo4jPassword = $vars?.NEO4J_PASSWORD || '';
const authHeader    = 'Basic ' + Buffer.from('neo4j:' + neo4jPassword).toString('base64');

try {
  const response = await axios.post(
    neo4jUrl,
    {
      statements: [{
        statement: "MATCH (pre:Concept {course_id: $courseId})-[:PREREQUISITE_FOR]->" +
                   "(target:Concept {course_id: $courseId}) " +
                   "WHERE target.name CONTAINS $topic " +
                   "RETURN pre.name AS prerequisite, pre.chapter AS chapter " +
                   "ORDER BY pre.chapter",
        parameters: { topic, courseId }
      }]
    },
    { headers: { 'Content-Type': 'application/json', 'Authorization': authHeader } }
  );

  const rows = response.data?.results?.[0]?.data;
  if (!rows || rows.length === 0) { return 'No prerequisites found for this topic.'; }

  return 'Prerequisites for this topic:\n' + rows
    .map(r => `- ${r.row[0]} (Chapter ${r.row[1]})`)
    .join('\n');

} catch (error) {
  return 'ERROR: ' + error.message;
}
